── SUPERSEDED 2026-10-06 by ADR-1709 (LIVE-747). The owner reworked pricing into a five-tier ladder with Collective back as its own plan, so this probe now fails by design. Original probe, kept verbatim: node -e 'const fs=require("fs");const rd=(p)=>fs.readFileSync(p,"utf8");const bad=[];
const plans=rd("lib/pricing/plans.ts"),keys=rd("lib/billing/pricing-keys.ts"),disp=rd("lib/pricing/display.ts"),gates=rd("lib/pricing/gates.ts");
const list=(s,n)=>{const m=s.match(new RegExp(n+"[^=]*=\\s*\\[([^\\]]*)\\]"));return m?m[1]:null};
const item=(s,n)=>{const i=s.indexOf(n+":");return i<0?null:s.slice(i,s.indexOf("\n  }",i))};
const sp=list(plans,"SPACE_PLANS");
if(sp===null)bad.push("SPACE_PLANS not found");
else{if(sp.includes("collective"))bad.push("collective still in SPACE_PLANS");
for(const p of ["free","business","nonprofit","independent"])if(!sp.includes(p))bad.push("SPACE_PLANS lost "+p)}
const bb=item(keys,"business_base");
if(!bb)bad.push("business_base not found");else if(!/amountsFromMonthly\(4900,\s*4900\)/.test(bb))bad.push("business_base is not $49");
const ret=list(keys,"RETIRED_CATALOG_ITEM_KEYS"),cat=list(keys,"CATALOG_ITEM_KEYS");
if(ret===null)bad.push("RETIRED_CATALOG_ITEM_KEYS not found");else if(!ret.includes("collective_base"))bad.push("collective_base is not retired in the catalog");
const seat=item(keys,"operator_seat");
if(!seat)bad.push("operator_seat not found");
else{if(/placeholder:\s*true/.test(seat))bad.push("operator_seat is still a placeholder");
if(!/amountsFromMonthly\(1200,\s*1200\)/.test(seat))bad.push("operator_seat is not $12")}
const tr=keys.match(/NETWORK_TAKE_RATE_DEFAULT[^=]*=\s*\{([\s\S]*?)\n\}/);
if(!tr)bad.push("NETWORK_TAKE_RATE_DEFAULT not found");
else{if(tr[1].includes("collective:"))bad.push("collective rung still in the take-rate ladder");
for(const r of ["free:","paid:","nonprofit:"])if(!tr[1].includes(r))bad.push("take-rate ladder lost the "+r+" rung")}
const mg=gates.match(/space_memberships:\s*\{[^}]+\}/);
if(!mg)bad.push("space_memberships gate missing");else if(/minEntitlement:\s*.business./.test(mg[0]))bad.push("space_memberships is still a Business plan wall");
const adv=list(disp,"ADVERTISED_SPACE_PLANS");
if(adv===null)bad.push("ADVERTISED_SPACE_PLANS not found");
else{if(adv.includes("independent"))bad.push("Independent is advertised; the owner ruling hides it");
for(const p of ["business","nonprofit"])if(!adv.includes(p))bad.push("ADVERTISED_SPACE_PLANS lost "+p)}
if(cat===null)bad.push("CATALOG_ITEM_KEYS not found");else if(!cat.includes("independent_base"))bad.push("independent_base left the live catalog; Independent is kept, only unadvertised");
if(!item(keys,"independent_base"))bad.push("independent_base has no catalog item, so it mints no Stripe price");
if(ret!==null&&ret.includes("independent_base"))bad.push("independent_base was retired; its prices stay live for a hand-sold deal");
for(const f of ["app/(marketing)/pricing/page.tsx","lib/pricing/pricing-page.ts","lib/page-editor/templates/pricing.ts"])if(fs.existsSync(f)&&/Collective/.test(rd(f)))bad.push("retired tier still names the merged plan: "+f);
const ctl=[];
if(!(list(plans.replace("SPACE_PLANS = [","SPACE_PLANS = [ collective,"),"SPACE_PLANS")||"").includes("collective"))ctl.push("SPACE_PLANS arm is blind");
if(!/placeholder:\s*true/.test(item(keys.replace("operator_seat:","operator_seat:\n    placeholder: true,"),"operator_seat")||""))ctl.push("operator_seat arm is blind");
if(!(list(keys.replace("RETIRED_CATALOG_ITEM_KEYS: readonly string[] = [","RETIRED_CATALOG_ITEM_KEYS: readonly string[] = [ independent_base,"),"RETIRED_CATALOG_ITEM_KEYS")||"").includes("independent_base"))ctl.push("retired-keys arm is blind");
if(ctl.length)bad.push("POSITIVE CONTROL FAILED: "+ctl.join(", "));
if(bad.length){console.error(bad.join("; "));process.exit(1)}'
